export type HotFileWriteOwnerStatus =
  | "claimed"
  | "reentrant"
  | "conflict"
  | "released"
  | "rolled-back";

export interface HotFileWriteOwnerHolder {
  readonly ownerId: string;
  readonly claimedAt: number;
}

export interface HotFileWriteOwnerClaim {
  readonly ok: boolean;
  readonly status: "claimed" | "reentrant" | "conflict";
  readonly filePath: string;
  readonly ownerId: string;
  readonly token?: string;
  readonly holder?: HotFileWriteOwnerHolder;
}

export interface HotFileWriteOwnerRelease {
  readonly ok: boolean;
  readonly status: "released" | "rolled-back" | "not-released";
  readonly filePath: string;
  readonly ownerId: string;
}

export interface FileMutationQueueOptions {
  readonly timeoutMs?: number;
  readonly signal?: AbortSignal;
}

/**
 * Adapter for the existing fileMutation lease queue. The hot-file owner module
 * deliberately does not implement scheduling, capacity, FIFO, or timeout logic.
 */
export type FileMutationQueueRunner = <T>(
  filePath: string,
  task: () => Promise<T>,
  options?: FileMutationQueueOptions,
) => Promise<T>;

export interface HotFileWriteOperationOptions extends FileMutationQueueOptions {
  /** The existing fileMutation queue adapter. */
  readonly queue: FileMutationQueueRunner;
}

interface OwnerRecord {
  readonly ownerId: string;
  readonly token: string;
  readonly claimedAt: number;
}

let tokenCounter = 0;

function nextToken(): string {
  tokenCounter += 1;
  return `hfwo-${Date.now().toString(36)}-${tokenCounter.toString(36)}`;
}

function validateIdentity(filePath: string, ownerId: string): void {
  if (typeof filePath !== "string" || filePath.length === 0) {
    throw new TypeError("filePath must be a non-empty string");
  }
  if (typeof ownerId !== "string" || ownerId.length === 0) {
    throw new TypeError("ownerId must be a non-empty string");
  }
}

/**
 * A process-local ownership ledger. JavaScript's run-to-completion property makes
 * each claim atomic with respect to other claims in the same runtime.
 */
export class HotFileWriteOwnerRegistry {
  private readonly owners = new Map<string, OwnerRecord>();

  claim(filePath: string, ownerId: string): HotFileWriteOwnerClaim {
    validateIdentity(filePath, ownerId);

    const current = this.owners.get(filePath);
    if (current) {
      if (current.ownerId === ownerId) {
        return {
          ok: true,
          status: "reentrant",
          filePath,
          ownerId,
          token: current.token,
          holder: this.publicHolder(current),
        };
      }

      return {
        ok: false,
        status: "conflict",
        filePath,
        ownerId,
        holder: this.publicHolder(current),
      };
    }

    const record: OwnerRecord = {
      ownerId,
      token: nextToken(),
      claimedAt: Date.now(),
    };
    this.owners.set(filePath, record);

    return {
      ok: true,
      status: "claimed",
      filePath,
      ownerId,
      token: record.token,
      holder: this.publicHolder(record),
    };
  }

  release(
    filePath: string,
    ownerId: string,
    token: string,
    rollback = false,
  ): HotFileWriteOwnerRelease {
    validateIdentity(filePath, ownerId);
    const current = this.owners.get(filePath);
    if (!current || current.ownerId !== ownerId || current.token !== token) {
      return {
        ok: false,
        status: "not-released",
        filePath,
        ownerId,
      };
    }

    this.owners.delete(filePath);
    return {
      ok: true,
      status: rollback ? "rolled-back" : "released",
      filePath,
      ownerId,
    };
  }

  rollback(filePath: string, ownerId: string, token: string): HotFileWriteOwnerRelease {
    return this.release(filePath, ownerId, token, true);
  }

  holder(filePath: string): HotFileWriteOwnerHolder | undefined {
    const current = this.owners.get(filePath);
    return current ? this.publicHolder(current) : undefined;
  }

  has(filePath: string, ownerId: string): boolean {
    return this.owners.get(filePath)?.ownerId === ownerId;
  }

  private publicHolder(record: OwnerRecord): HotFileWriteOwnerHolder {
    return {
      ownerId: record.ownerId,
      claimedAt: record.claimedAt,
    };
  }
}

const defaultRegistry = new HotFileWriteOwnerRegistry();

export function claimHotFileWriteOwner(
  filePath: string,
  ownerId: string,
): HotFileWriteOwnerClaim {
  return defaultRegistry.claim(filePath, ownerId);
}

export function releaseHotFileWriteOwner(
  filePath: string,
  ownerId: string,
  token: string,
): HotFileWriteOwnerRelease {
  return defaultRegistry.release(filePath, ownerId, token);
}

export function rollbackHotFileWriteOwner(
  filePath: string,
  ownerId: string,
  token: string,
): HotFileWriteOwnerRelease {
  return defaultRegistry.rollback(filePath, ownerId, token);
}

export function getHotFileWriteOwnerHolder(
  filePath: string,
): HotFileWriteOwnerHolder | undefined {
  return defaultRegistry.holder(filePath);
}

/**
 * Runs a write in the caller's existing fileMutation queue while holding the
 * hot-file ownership lease. A conflicting owner is rejected before it can be
 * queued. A queue rejection or write error rolls the claim back.
 */
export async function runWithHotFileWriteOwner<T>(
  filePath: string,
  ownerId: string,
  write: () => Promise<T> | T,
  options: HotFileWriteOperationOptions,
): Promise<T> {
  if (!options || typeof options.queue !== "function") {
    throw new TypeError("options.queue must be the existing fileMutation queue runner");
  }

  const claim = defaultRegistry.claim(filePath, ownerId);
  if (!claim.ok || !claim.token) {
    throw new HotFileWriteOwnerConflictError(filePath, ownerId, claim.holder);
  }

  try {
    const result = await options.queue(filePath, async () => await write(), options);
    defaultRegistry.release(filePath, ownerId, claim.token);
    return result;
  } catch (error) {
    defaultRegistry.rollback(filePath, ownerId, claim.token);
    throw error;
  }
}

export class HotFileWriteOwnerConflictError extends Error {
  readonly code = "HOT_FILE_WRITE_OWNER_CONFLICT";
  readonly filePath: string;
  readonly requestedOwnerId: string;
  readonly holder?: HotFileWriteOwnerHolder;

  constructor(
    filePath: string,
    requestedOwnerId: string,
    holder?: HotFileWriteOwnerHolder,
  ) {
    super(
      holder
        ? `Write ownership conflict for ${filePath}; holder is ${holder.ownerId}`
        : `Write ownership conflict for ${filePath}`,
    );
    this.name = "HotFileWriteOwnerConflictError";
    this.filePath = filePath;
    this.requestedOwnerId = requestedOwnerId;
    this.holder = holder;
  }
}

// Short aliases retained for callers that model this as a write-owner guard.
export const claimWriteOwner = claimHotFileWriteOwner;
export const releaseWriteOwner = releaseHotFileWriteOwner;
export const rollbackWriteOwner = rollbackHotFileWriteOwner;
export const withHotFileWriteOwner = runWithHotFileWriteOwner;

